import{useState}from'react';import{Link}from'react-router-dom';import{Heart,Eye,ShieldCheck,Truck,MessageCircle,ShoppingBag,Boxes}from'lucide-react';import{Product}from'../data/products';import{useStore}from'../context/Store';import{getCommerceSettings}from'../data/siteConfig';import BrandLogo from'./BrandLogo';
export default function ProductCard({p}:{p:Product}){const[commerce]=useState(getCommerceSettings);const{user,addCart,saved,toggleSave,compare,toggleCompare}=useStore();const priceVisible=user.status==='approved'||commerce.guestPricing==='visible';const margin=Math.max(0,Math.round((p.msrp-p.price)/p.msrp*100));return <article className="wholesale-product-card"><div className="wpc-media"><div className="wpc-badges"><span>{p.tags[0]}</span>{p.verified&&<span className="verified"><ShieldCheck/>Verified</span>}</div><button className={'wpc-save '+(saved.includes(p.id)?'active':'')} onClick={()=>toggleSave(p.id)} aria-label={saved.includes(p.id)?'Remove saved product':'Save product'}><Heart/></button><Link className="wpc-image" to={'/products/'+p.slug}><img src={p.image} alt={`${p.brand} ${p.name}`} loading="lazy" decoding="async"/></Link><Link className="wpc-quick" to={'/products/'+p.slug}><Eye/>Quick view</Link></div><div className="wpc-body"><div className="wpc-brand-row"><Link to={'/brand/'+p.brand.toLowerCase().replace(/[^a-z0-9]+/g,'-')}><BrandLogo brand={p.brand} variant="micro" showName/></Link><span>{p.size}</span></div><Link className="wpc-title" to={'/products/'+p.slug}>{p.name}</Link><small className="wpc-sku">SKU {p.sku} · {p.category}</small><div className="wpc-social"><span><b>{p.rating}</b> ★★★★★</span><Link to={`/products/${p.slug}#reviews`}>{p.reviews.toLocaleString()} ratings</Link><span>{p.orders.toLocaleString()} ordered*</span></div>{priceVisible?<div className="wpc-pricing"><div><b>${p.price.toFixed(2)}–${(p.price*1.08).toFixed(2)}</b><span>/ unit</span></div><p><del>${p.msrp.toFixed(2)} MSRP</del><strong>{margin}% retail margin</strong></p></div>:<Link className="wpc-price-lock" to="/login"><ShieldCheck/>Sign in to view wholesale pricing</Link>}<div className="wpc-commercial"><div><small>MINIMUM</small><b>{p.moq} {p.moq===1?'case':'cases'}</b></div><div><small>CASE PACK</small><b>{p.casePack} units</b></div><div><small>DISPATCH</small><b>{p.leadTime}</b></div></div>{priceVisible&&<div className="wpc-order-value"><Boxes/><span>Opening order</span><b>${(p.price*p.casePack*p.moq).toFixed(2)}</b></div>}<div className="wpc-availability"><span className={p.stock?'available':'unavailable'}>{p.stock?`${p.stock} cases available`:'Currently unavailable'}</span><span><Truck/>US inventory</span></div><div className="wpc-supplier"><div><span>Supplied by</span><Link to="/supplier/meridian">{p.supplier}</Link></div>{p.verified&&<b><ShieldCheck/>Business verified</b>}</div><div className="wpc-actions"><Link to="/supplier/meridian"><MessageCircle/>Contact</Link><button disabled={!p.stock} onClick={()=>addCart(p)}><ShoppingBag/>{p.stock?'Add case':'Unavailable'}</button></div><label className="wpc-compare"><input type="checkbox" checked={compare.includes(p.id)} onChange={()=>toggleCompare(p.id)}/><span>Compare product</span><em>+{Math.min(5,Math.max(2,p.gallery.length-1))} buying options</em></label></div></article>}
