import{useState}from'react';import{Link}from'react-router-dom';import{ShieldCheck,MessageCircle,FileText,MapPin,Clock3,Truck,Check,Download,Heart,Share2}from'lucide-react';import{products,brands,categories}from'../data/products';import ProductCard from'../components/ProductCard';import{useStore}from'../context/Store';
export default function SupplierPage(){const[tab,setTab]=useState('Products');const{showToast}=useStore();return <div className="supplier-page"><section className="supplier-hero"><div className="container"><div className="supplier-identity"><span>MS</span><div><div className="supplier-name"><h1>Meridian Supply Co.</h1><b><ShieldCheck/> Verified supplier profile</b></div><p>Beauty, fragrance and personal-care wholesale distribution · United States inventory</p><div><span><MapPin/> United States</span><span><Clock3/> Nearly 30 years*</span><span><Truck/> Domestic fulfillment</span></div></div></div><aside><button onClick={()=>showToast('Supplier saved')}><Heart/> Save supplier</button><button onClick={async()=>{await navigator.clipboard?.writeText(window.location.href);showToast('Supplier profile link copied')}}><Share2/> Share</button><button className="btn primary" onClick={()=>showToast('Message workspace opened')}><MessageCircle/> Contact supplier</button></aside></div></section><div className="supplier-nav"><div className="container">{['Products','Company profile','Capabilities','Documents','Reviews'].map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}<Link to="/request-quote">Request quotation</Link></div></div><section className="supplier-overview container"><div className="supplier-kpis">{[['4.8 / 5','Buyer rating'],['≤ 4 hours','Target response'],['96','Catalog products'],[String(brands.length),'Featured brands'],['US','Inventory location']].map(([a,b])=><div key={b}><b>{a}</b><span>{b}</span></div>)}</div><div className="supplier-assurance"><ShieldCheck/><div><b>Supplier credentials and commercial relationships</b><p>Company, authorization and brand-relationship information should be displayed only after documentation is reviewed. This demonstration intentionally avoids unsupported authorization claims.</p></div><Link to="/trademark-disclaimer">Review disclosure</Link></div>{tab==='Products'&&<><div className="supplier-catalog-head"><div><p className="eyebrow">PRODUCT CATALOG</p><h2>Wholesale assortment</h2></div><div>{categories.slice(0,5).map(x=><Link key={x} to={'/shop?category='+x}>{x}</Link>)}</div></div><div className="product-grid supplier-products">{products.slice(0,12).map(p=><ProductCard p={p} key={p.id}/>)}</div></>}{tab==='Company profile'&&<Profile/>}{tab==='Capabilities'&&<Capabilities/>}{tab==='Documents'&&<Documents/>}{tab==='Reviews'&&<SupplierReviews/>}</section></div>}
function Profile(){return <div className="supplier-tab-content"><article><p className="eyebrow">COMPANY PROFILE</p><h2>Distribution experience built around long-term business relationships.</h2><p>Meridian Supply Co. is a demonstration identity for an established wholesale distributor modernizing its business infrastructure. Final operating history, facility information, business registrations and brand relationships must be verified before public launch.</p><div className="profile-table">{[['Business type','Wholesale distributor'],['Primary categories','Beauty, fragrance and personal care'],['Service market','Qualified United States businesses'],['Order model','Case-level B2B purchasing'],['Account support','Dedicated service workflow'],['Legal verification','Required before launch']].map(([a,b])=><div key={a}><span>{a}</span><b>{b}</b></div>)}</div></article><aside><h3>Company highlights</h3>{['Domestic inventory workflows','Business account verification','Wholesale pricing tiers','Order and reorder management','Commercial-document support'].map(x=><p key={x}><Check/>{x}</p>)}</aside></div>}
function Capabilities(){return <div className="capability-grid">{[['Inventory & assortment','Catalog discovery, availability indicators and case-level product information.'],['Account pricing','Protected wholesale prices and tier-based pricing architecture.'],['Order fulfillment','Ground, expedited and scheduled freight workflows.'],['Commercial support','RFQs, product questions and documentation requests.'],['Buyer operations','Saved products, comparison, reordering and account management.'],['API readiness','Data architecture designed for ERP, inventory and payment integrations.']].map(([a,b])=><div key={a}><h3>{a}</h3><p>{b}</p></div>)}</div>}
function Documents(){const{showToast}=useStore();return <div className="supplier-documents">{['Business registration','Resale and tax framework','Brand relationship documentation','Product specification library','Returns and fulfillment policy','Accessibility and legal disclosures'].map((x,i)=><div key={x}><span><FileText/></span><p><b>{x}</b><small>{i<2?'Verification required':'Available by account or request'}</small></p><button onClick={()=>showToast(`${x} request added`)}><Download/> Request</button></div>)}</div>}
function SupplierReviews(){return <div className="supplier-reviews"><div><b>4.8</b><span>★★★★★</span><small>Development review architecture</small></div>{['Product quality','Supplier service','On-time dispatch','Communication'].map((x,i)=><p key={x}><span>{x}</span><i><em style={{width:`${95-i*2}%`}}/></i><b>{(4.8-i*.1).toFixed(1)}</b></p>)}</div>}
