const CATALOG_VERSION='3';
export function hydrateCatalog(){if(typeof window==='undefined')return;try{const saved=localStorage.getItem('ms-admin-catalog-version')===CATALOG_VERSION?localStorage.getItem('ms-admin-products'):null;if(saved){const parsed=JSON.parse(saved);if(Array.isArray(parsed)&&parsed.length){products=parsed;brands=[...new Set(products.map(p=>p.brand))];categories=[...new Set(products.map(p=>p.category))]}}const taxonomy=localStorage.getItem('ms-admin-taxonomy');if(taxonomy){const parsed=JSON.parse(taxonomy);if(Array.isArray(parsed.brands))brands=parsed.brands;if(Array.isArray(parsed.categories))categories=parsed.categories}}catch{}}
export function persistCatalog(next:Product[]){products=next;brands=[...new Set(next.map(p=>p.brand))];categories=[...new Set(next.map(p=>p.category))];if(typeof window!=='undefined'){localStorage.setItem('ms-admin-products',JSON.stringify(next));localStorage.setItem('ms-admin-catalog-version',CATALOG_VERSION)}}
export function persistBrands(next:string[]){brands=next;if(typeof window!=='undefined')localStorage.setItem('ms-admin-taxonomy',JSON.stringify({brands,categories}))}
export function persistCategories(next:string[]){categories=next;if(typeof window!=='undefined')localStorage.setItem('ms-admin-taxonomy',JSON.stringify({brands,categories}))}
export function resetCatalog(){if(typeof window!=='undefined')localStorage.removeItem('ms-admin-products');localStorage.removeItem('ms-admin-catalog-version');localStorage.removeItem('ms-admin-taxonomy');window.location.reload()}

